#include "TestCommon.h"
int main(int argc,char**argv){using namespace gpuls;try{require(argc==3,"G64BatchOutputAudit input output");Context c;auto refs=cases(argv[1],true);std::ostringstream log;log<<std::setprecision(17)<<"{\"runs\":[";bool first=true;unsigned totalDifferences=0;for(unsigned count:{1u,10u,100u,2839u}){Pack p(count);for(unsigned i=0;i<count;i++)p.system(i,*refs[i%3]->w);Engine baseline(c,p.bytes.size(),p.scratchBytes);baseline.layout=0;baseline.prepare(p);for(unsigned k:{1u,5u}){auto b=baseline.run(k,false,false,false);for(unsigned i=0;i<count;i++){auto st=getStatus(b,p.systems[i]);require(st.code==0&&st.corrections==k&&st.done,"Baseline audit status");if(i<3)require(checkOutput(*refs[i%3],b,p.systems[i]).pass,"Baseline audit strict");}for(unsigned mode:{1u,2u}){Engine candidate(c,p.bytes.size(),p.scratchBytes);candidate.layout=mode;candidate.prepare(p);auto r=candidate.run(k,false,false,false);unsigned differences=0;double maxDelta=0;for(unsigned i=0;i<count;i++){auto&m=p.systems[i];auto st=getStatus(r,m);require(st.code==0&&st.corrections==k&&st.done,"Candidate audit status");bool same=std::memcmp(b.bytes.data()+m.outputOffset,r.bytes.data()+m.outputOffset,m.n*8)==0;if(!same){differences++;auto err=checkOutput(*refs[i%3],r,m);require(err.pass,"Candidate audit strict");std::ostringstream detail;detail<<"{\"system\":"<<i<<",\"baselineBits\":[";for(unsigned j=0;j<m.n;j++){uint64_t left,right;std::memcpy(&left,b.bytes.data()+m.outputOffset+j*8,8);std::memcpy(&right,r.bytes.data()+m.outputOffset+j*8,8);if(j)detail<<',';detail<<'['<<left<<','<<right<<']';double a,z;std::memcpy(&a,&left,8);std::memcpy(&z,&right,8);maxDelta=std::max(maxDelta,std::abs(a-z));}detail<<"]}";text(fs::path(argv[2])/(std::to_string(count)+"-"+std::to_string(k)+"-"+std::to_string(mode)+"-"+std::to_string(i)+".json"),detail.str());}}totalDifferences+=differences;if(!first)log<<',';first=false;log<<"{\"systems\":"<<count<<",\"corrections\":"<<k<<",\"layout\":"<<mode<<",\"nonBitwiseSlots\":"<<differences<<",\"maxScaledDifference\":"<<maxDelta<<'}';}}}log<<"],\"nonBitwiseSlots\":"<<totalDifferences<<",\"timestamped\":false}";text(fs::path(argv[2])/"batch-bit-audit.json",log.str());c.audit();return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
